/* cppi::ae780894b2d15b0878bccd9daf48343a43ecc21ae8e070ef1e6643456a83dfdb */
SELECT instrument_id, rating_class_number, rating_date, moodys_rating_id, rating_level, rating_class_text, security_class_code, security_class_text, security_class_short_description, duration_code, duration_text, duration_short_description, seniority_code, seniority_text, seniority_short_description, evaluation_type_code, evaluation_type_text, shadow_code, shadow_text, shadow_short_description, rating_subclass_code, rating_subclass_text, currency_capd_code, currency_capd_text, rating_text, credit_grade, rating_rank, rating_direction_code, rating_direction_text, rating_direction_short_description, rating_type_code, rating_type_text, rating_type_short_description, rating_enhancement_level, rating_local_date, rating_termination_date, rating_termination_local_date, rating_reason_code, rating_reason_text, rating_currency_code, rating_currency_text, rating_currency_iso_code, rating_monitor_indicator, rating_office_id, shelf_type_code, shelf_type_text, shelf_type_short_description, initial_rating_indicator, business_date, arrival_time, feed_name, file_type FROM market.moodys_security_ratings_latest ORDER BY rating_date DESC
LIMIT 500

